def line_collision_check(first, second, obstacleList):
    x1 = first[0]
    y1 = first[1]
    x2 = second[0]
    y2 = second[1]
    try:
        a = y2 - y1
        b = -(x2 - x1)
        c = y2 * (x2 - x1) - x2 * (y2 - y1)
    except ZeroDivisionError:
        return False
    for ox, oy, size in obstacleList:
        d = abs(a * ox + b * oy + c) / math.hypot(a, b)
        if d <= size:
            return False
    return True
